local Glazier = {}
local PRODUCTS = {
    window = { name = "Okno", glassCost = 2, leadCost = 1, woodCost = 2, time = 3, cost = 40, lightBonus = 5, description = "Okensko steklo z okvirjem." },
    stained_window = { name = "Vitrajno okno", glassCost = 4, leadCost = 2, woodCost = 2, time = 14, cost = 300, lightBonus = 8, prestige = 15, faith = 10, description = "Barvno vitrajno okno." },
    leaded_light = { name = "Svinčeno okno", glassCost = 3, leadCost = 3, time = 7, cost = 120, lightBonus = 6, description = "Svinčeno mrežasto okno." },
    mirror = { name = "Zrcalo", glassCost = 3, silverCost = 1, woodCost = 2, time = 8, cost = 200, lightBonus = 4, happiness = 5, prestige = 5, description = "Zrcalo s srebro." },
    skylight = { name = "Strešno okno", glassCost = 5, leadCost = 2, woodCost = 3, time = 10, cost = 250, lightBonus = 12, description = "Strešna luč." },
    display_case = { name = "Vitrina", glassCost = 6, woodCost = 3, time = 7, cost = 180, lightBonus = 3, prestige = 8, description = "Vitrina za razstave." },
}
local BUILDINGS = {
    workshop = { name = "Steklarjeva delavnica", cost = { gold = 300, wood = 100 }, upkeep = 8, qualityBonus = 5 },
    glazing_shop = { name = "Ostekljevalnica", cost = { gold = 800, wood = 200, stone = 200 }, upkeep = 20, qualityBonus = 15 },
    lead_workshop = { name = "Svinčarska delavnica", cost = { gold = 500, wood = 100, stone = 100, lead = 50 }, upkeep = 12, qualityBonus = 10 },
    royal_glaziery = { name = "Kraljevska ostekljevalnica", cost = { gold = 3000, wood = 400, stone = 600 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 15 },
}
Glazier.glassStock = 12; Glazier.leadStock = 8; Glazier.woodStock = 10; Glazier.silverStock = 3
Glazier.productStock = {}; Glazier.buildings = {}; Glazier.glazier = nil; Glazier.activeMaking = {}; Glazier.totalProducts = 0; Glazier.dayTimer = 0
function Glazier.init() Glazier.glassStock=12; Glazier.leadStock=8; Glazier.woodStock=10; Glazier.silverStock=3; Glazier.productStock={}; Glazier.buildings={}; Glazier.glazier=nil; Glazier.activeMaking={}; Glazier.totalProducts=0; Glazier.dayTimer=0; print("[Glazier] Royal Glazier & Window Maker System initialized (6 products, 4 buildings)") end
function Glazier.hireGlazier(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Glazier.glazier={name=n or ("Steklar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Steklar najet: %s (spretnost: %d)",Glazier.glazier.name,s),"success") end; return true end
function Glazier.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Glazier.build(id) local ok,e=Glazier.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Glazier.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Glazier.getQualityBonus() local b=0; for _,bd in ipairs(Glazier.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Glazier.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and Glazier.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.leadCost and Glazier.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.woodCost and Glazier.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and Glazier.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if #Glazier.buildings==0 then return false,"Potrebna delavnica" end; if not Glazier.glazier then return false,"Potreben steklar" end; return true end
function Glazier.make(pt) local ok,e=Glazier.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then Glazier.glassStock=Glazier.glassStock-d.glassCost end; if d.leadCost then Glazier.leadStock=Glazier.leadStock-d.leadCost end; if d.woodCost then Glazier.woodStock=Glazier.woodStock-d.woodCost end; if d.silverCost then Glazier.silverStock=Glazier.silverStock-d.silverCost end; local t=d.time; if Glazier.glazier then t=math.max(1,t-math.floor(Glazier.glazier.skill/12)) end; table.insert(Glazier.activeMaking,{id="window_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,lightBonus=d.lightBonus or 0,prestige=d.prestige or 0,faith=d.faith or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ostekljevanje: %s (%d dni)",d.name,t),"info") end; return true end
function Glazier.completeMaking(m) local q=1.0+(Glazier.getQualityBonus()/100); if Glazier.glazier then q=q+(Glazier.glazier.skill/200) end; q=math.min(2.0,q); Glazier.productStock[m.productType]=(Glazier.productStock[m.productType] or 0)+1; Glazier.totalProducts=Glazier.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if m.faith>0 and _G.Religion then pcall(_G.Religion.addFaith,m.faith) end; if Glazier.glazier then Glazier.glazier.itemsMade=Glazier.glazier.itemsMade+1; if math.random()<0.15 then Glazier.glazier.skill=math.min(100,Glazier.glazier.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Okno izdelano: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Glazier.update(dt) if not _G.state then return end; Glazier.dayTimer=Glazier.dayTimer+dt; if Glazier.dayTimer>=30 then Glazier.dayTimer=0; for i=#Glazier.activeMaking,1,-1 do local m=Glazier.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Glazier.completeMaking(m); table.remove(Glazier.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Glazier.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Glazier.glazier then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Glazier.getStats() return {glassStock=Glazier.glassStock,leadStock=Glazier.leadStock,woodStock=Glazier.woodStock,silverStock=Glazier.silverStock,productStock=Glazier.productStock,numBuildings=#Glazier.buildings,hasGlazier=Glazier.glazier~=nil,glazierName=Glazier.glazier and Glazier.glazier.name or "—",glazierSkill=Glazier.glazier and Glazier.glazier.skill or 0,activeMaking=#Glazier.activeMaking,totalProducts=Glazier.totalProducts} end
return Glazier
